const real = name => $(name).all().map(i => i.json).filter(r => Object.keys(r).length > 0);
const mastery = real('Get All Mastery');
const attempts = real('Get Week Attempts');
const plans = real('Get Week Plans');
const skills = real('Get Skill Map');
const skillName = code => { const s = skills.find(x => x.skill_code === code); return s ? s.skill_name : code; };
const skillOrder = code => { const s = skills.find(x => x.skill_code === code); return s ? Number(s.level_order) : 99; };
const labels = { mastered: 'متقن', learning: 'قيد التعلّم', gap: 'فجوة', needs_help: 'يحتاج تدخّل' };
const cell = 'style="border:1px solid #ccc;padding:4px 8px"';

const groups = [...new Set(mastery.map(m => m.group_code || 'بدون مجموعة'))].sort();
let html = '<div dir="rtl" style="font-family:Arial,sans-serif">';
html += '<h2>التقرير الأسبوعي — استعادة التعلّم</h2>';
html += '<p>الأسبوع المنتهي في ' + $now.toFormat('yyyy-MM-dd') + '. يستخدم التقرير الرموز المستعارة فقط ومخصّص للمعلم المسؤول.</p>';
html += '<p><b>محاولات هذا الأسبوع:</b> ' + attempts.length + ' — <b>الخطط:</b> ' + plans.filter(p => p.status === 'approved').length + ' معتمدة، ' + plans.filter(p => p.status === 'pending_review').length + ' بانتظار المراجعة، ' + plans.filter(p => p.status === 'needs_revision').length + ' تحتاج تعديل.</p>';

for (const g of groups) {
  const rows = mastery.filter(m => (m.group_code || 'بدون مجموعة') === g);
  const students = [...new Set(rows.map(r => r.student_code))];
  const studentAttempts = attempts.filter(a => students.includes(a.student_code));
  const avg = studentAttempts.length ? Math.round(studentAttempts.reduce((s, a) => s + Number(a.score || 0), 0) / studentAttempts.length) : null;
  html += '<h3>المجموعة ' + g + ' (' + students.length + ' طلاب)</h3>';
  html += '<p>محاولات هذا الأسبوع: ' + studentAttempts.length + (avg === null ? '' : ' — متوسط النتيجة: ' + avg + ' من 100') + '</p>';
  const codes = [...new Set(rows.map(r => r.skill_code))].sort((a, b) => skillOrder(a) - skillOrder(b));
  html += '<table style="border-collapse:collapse"><tr><th ' + cell + '>المهارة</th><th ' + cell + '>متقن</th><th ' + cell + '>قيد التعلّم</th><th ' + cell + '>فجوة</th><th ' + cell + '>يحتاج تدخّل</th><th ' + cell + '>متوسط الإتقان</th></tr>';
  for (const c of codes) {
    const r = rows.filter(x => x.skill_code === c);
    const count = st => r.filter(x => x.status === st).length;
    const avgM = Math.round(r.reduce((s, x) => s + Number(x.mastery || 0), 0) / r.length);
    html += '<tr><td ' + cell + '>' + skillName(c) + ' (' + c + ')</td><td ' + cell + '>' + count('mastered') + '</td><td ' + cell + '>' + count('learning') + '</td><td ' + cell + '>' + count('gap') + '</td><td ' + cell + '>' + count('needs_help') + '</td><td ' + cell + '>' + avgM + '</td></tr>';
  }
  html += '</table>';
  const help = rows.filter(r => r.status === 'needs_help');
  if (help.length) {
    html += '<p><b>يحتاجون تدخّلًا:</b></p><ul>';
    for (const h of help) html += '<li>' + h.student_code + ': ' + skillName(h.skill_code) + ' (إتقان ' + h.mastery + ')</li>';
    html += '</ul>';
  }
  const commonGaps = codes.map(c => ({ c, n: rows.filter(x => x.skill_code === c && (x.status === 'gap' || x.status === 'needs_help')).length })).filter(x => x.n >= 2);
  if (commonGaps.length) html += '<p><b>فجوات مشتركة تصلح لجلسة جماعية:</b> ' + commonGaps.map(x => skillName(x.c) + ' (' + x.n + ' طلاب)').join('، ') + '</p>';
}
if (!groups.length) html += '<p>لا توجد بيانات إتقان بعد.</p>';
html += '<p style="color:#666">الأرقام مساعدة للقرار التربوي ولا تحلّ محله.</p></div>';
return [{ json: { subject: 'التقرير الأسبوعي لاستعادة التعلّم — ' + $now.toFormat('yyyy-MM-dd'), html, groups: groups.length, attempts: attempts.length } }];
